// Package notebuilder tests — T-15 characterization (Phase 1).
//
// THE LAW (roadmap Phase 1 + task list standing orders): the Python
// characterization tests are ported FIRST, then the code; the goldens were
// GENERATED by running the unmodified Python reference app
// (assadigit/GitCurator @ 98f4fc7) via testdiff/goldens/dump_notebuilder.py
// — never hand-typed. Regenerate with:
//
//	python3 testdiff/goldens/dump_notebuilder.py
//
// Ported suites:
//   - app/tests/test_core.py TestNoteBuilder (all 8 tests — the sanitizer
//     battery against YAML injection)
//   - app/tests/test_phase1.py TestNoteFormat (all 4 tests — ownership
//     keys, banner, section inventory)
//   - app/tests/test_intakefix.py TestMissingRepoNote tests 1–3 (the
//     dedupe key, the .git suffix, the not-a-managed-note law). Its test
//     4 (VaultIndex dedupe-through-the-note) needs the Phase-2 store
//     layer — deliberately deferred (recorded in SESSION-005), NOT
//     weakened: T-25's vault_index port re-adds it against a real
//     VaultIndex.
//
// The golden corpus additionally pins the full note formats (6 synthetic
// repos + 5 missing-repo notes, byte-exact incl. the blank-line quirks),
// every sanitizer on hostile corpora (Python's UNICODE \s collapse
// included), the banner-gate traversal corpus, and the rating boundary
// tables. The volatile local date is normalized (<DATE>) at dump and test
// time; the real format is pinned by TestDateProcessedFormat.
package notebuilder

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

// ---------------------------------------------------------------------------
// Golden plumbing (notebuilder_corpus.golden.json — UseNumber so int-vs-
// float hostile values survive as json.Number for the any-typed fields).
// ---------------------------------------------------------------------------

func goldenBytes(t *testing.T, name string) []byte {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read golden %s (generate with testdiff/goldens/dump_notebuilder.py): %v", name, err)
	}
	return raw
}

func loadCorpus(t *testing.T) map[string]any {
	t.Helper()
	dec := json.NewDecoder(bytes.NewReader(goldenBytes(t, "notebuilder_corpus.golden.json")))
	dec.UseNumber()
	var doc map[string]any
	if err := dec.Decode(&doc); err != nil {
		t.Fatalf("decode corpus: %v", err)
	}
	return doc
}

func corpusSection(t *testing.T, doc map[string]any, key string) []any {
	t.Helper()
	v, ok := doc[key].([]any)
	if !ok {
		t.Fatalf("corpus section %q missing or wrong shape", key)
	}
	return v
}

// corpusInt decodes a golden number field.
func corpusFloat(t *testing.T, v any) float64 {
	t.Helper()
	n, ok := v.(json.Number)
	if !ok {
		t.Fatalf("corpus number field wrong type: %T", v)
	}
	f, err := n.Float64()
	if err != nil {
		t.Fatalf("corpus number field %q: %v", n.String(), err)
	}
	return f
}

func corpusInt(t *testing.T, v any) int {
	t.Helper()
	n, ok := v.(json.Number)
	if !ok {
		t.Fatalf("corpus number field wrong type: %T", v)
	}
	i, err := n.Int64()
	if err != nil {
		t.Fatalf("corpus number field %q: %v", n.String(), err)
	}
	return int(i)
}

func corpusString(t *testing.T, v any) string {
	t.Helper()
	s, ok := v.(string)
	if !ok {
		t.Fatalf("corpus string field wrong type: %T", v)
	}
	return s
}

// corpusValue keeps a hostile value as json.Number/string/bool/nil — the
// shapes Python str() meets.
func corpusValue(t *testing.T, v any) any {
	t.Helper()
	switch vv := v.(type) {
	case string, bool, nil, json.Number:
		return vv
	default:
		t.Fatalf("corpus value wrong type: %T", v)
		return nil
	}
}

// corpusValueList converts a JSON array of hostile values.
func corpusValueList(t *testing.T, v any) []any {
	t.Helper()
	arr, ok := v.([]any)
	if !ok {
		if v == nil {
			return nil
		}
		if s, isStr := v.(string); isStr {
			return []any{s} // Python: a str tags input becomes [tags]
		}
		t.Fatalf("corpus value list wrong type: %T", v)
	}
	out := make([]any, len(arr))
	for i, e := range arr {
		out[i] = corpusValue(t, e)
	}
	return out
}

// normNote mirrors the generator's dump-time normalization: the local
// date_processed line only (release dates / content stay byte-exact).
func normNote(text string) string {
	return dateProcessedRe.ReplaceAllString(text, "date_processed: <DATE>")
}

var dateProcessedRe = regexp.MustCompile(`date_processed: \d{4}-\d{2}-\d{2}`)
var dateRecordedRe = regexp.MustCompile(`date_recorded: \d{4}-\d{2}-\d{2}`)
var recordedAfterRe = regexp.MustCompile(`Recorded \d{4}-\d{2}-\d{2} after`)

func normMissing(text string) string {
	text = dateRecordedRe.ReplaceAllString(text, "date_recorded: <DATE>")
	return recordedAfterRe.ReplaceAllString(text, "Recorded <DATE> after")
}

