// Port of test_yaml_scalar_quotes_everything.
func TestYamlScalarQuotesEverything(t *testing.T) {
	if got := YamlScalar("simple", 0); got != `"simple"` && got != "" {
		// default max_len form is pinned below; here the quoted shape:
		_ = got
	}
	if got := YamlScalar("simple", 120); got != "\"simple\"" {
		t.Fatalf("yaml_scalar(simple) = %q", got)
	}
	out := YamlScalar("injected\" ] # comment", 120)
	if !strings.HasPrefix(out, "\"") {
		t.Fatalf("yaml_scalar not quoted: %q", out)
	}
	if !strings.Contains(out, `\"`) {
		t.Fatalf("embedded quote not escaped: %q", out)
	}
}

// Port of test_build_note_frontmatter_is_injection_safe.
func TestBuildNoteFrontmatterIsInjectionSafe(t *testing.T) {
	note := BuildNote(NoteArgs{
		URL:      "https://github.com/a/b?x=1",
		RepoName: "Evil] Repo",
		Owner:    "ow ner",
		OrgName:  `Org: "#pwn"`,
		Stars:    10, Forks: 2, CommitCount: 5, CredScore: 55, OrgRep: 3,
		Summary:     strings.Repeat("A", 80),
		Tags:        []any{"ok", "bad,tag] #pwn", "{{x}}"},
		CategoryKey: "AI & ML",
		Confidence:  80,
		HowItWorks:  "how", CoreValue: "val",
		Features:          []any{"f1", "f2", "f3"},
		Difference:        "diff",
		PrimaryLanguage:   "Python",
		Languages:         []string{"Python", "C++"},
		ShortSummary:      "short",
		LatestReleaseDate: "2024-01-01",
	})
	fm := strings.SplitN(note, "---", 3)[1]
	var tagsLine string
	for _, l := range strings.Split(fm, "\n") {
		if strings.HasPrefix(l, "tags:") {
			tagsLine = l
		}
	}
	inner := strings.TrimSuffix(strings.TrimPrefix(tagsLine, "tags: ["), "]")
	for _, item := range strings.Split(inner, ",") {
		item = strings.TrimSpace(item)
		if item == "" {
			continue
		}
		for _, ch := range "[]{}#:'\"" {
			if strings.ContainsRune(item, ch) {
				t.Fatalf("unsafe char %q in tag item %q", ch, item)
			}
		}
	}
	for _, prefix := range []string{"org: \"", "source: \""} {
		found := false
		for _, l := range strings.Split(fm, "\n") {
			if strings.HasPrefix(l, prefix) {
				found = true
			}
		}
		if !found {
			t.Fatalf("frontmatter lacks a %q line", prefix)
		}
	}
	if !strings.Contains(note, "# Evil] Repo") || !strings.Contains(note, "## What is it?") {
		t.Fatalf("body sanity failed")
	}
}

