// TestGoldenNotes pins the FULL build_note output for the 6 synthetic
// repos — byte-exact including the blank-line quirks (empty optional
// fields emit their template line as a blank; the aliases block carries a
// trailing newline before tags). Inputs are decoded from the golden with
// UseNumber so int-vs-float hostile values keep their Python str()
// shapes.
func TestGoldenNotes(t *testing.T) {
	doc := loadCorpus(t)
	for _, e := range corpusSection(t, doc, "notes") {
		p := e.([]any)
		label := corpusString(t, p[0])
		argsBytes, err := json.Marshal(p[1])
		if err != nil {
			t.Fatalf("%s: re-marshal args: %v", label, err)
		}
		dec := json.NewDecoder(bytes.NewReader(argsBytes))
		dec.UseNumber()
		var args NoteArgs
		if err := dec.Decode(&args); err != nil {
			t.Fatalf("%s: decode args: %v", label, err)
		}
		want := corpusString(t, p[2])
		got := normNote(BuildNote(args))
		if got != want {
			t.Fatalf("%s: note drifted.\n--- got (go) ---\n%s\n--- want (python) ---\n%s",
				label, got, want)
		}
	}
}

// TestGoldenMissingNotes pins the FULL build_missing_repo_note outputs.
func TestGoldenMissingNotes(t *testing.T) {
	doc := loadCorpus(t)
	for _, e := range corpusSection(t, doc, "missing_notes") {
		p := e.([]any)
		q := p[0].([]any)
		url, owner, repo := corpusString(t, q[0]), corpusString(t, q[1]), corpusString(t, q[2])
		strikes := corpusInt(t, q[3])
		want := corpusString(t, p[1])
		got := normMissing(BuildMissingRepoNote(url, owner, repo, strikes))
		if got != want {
			t.Fatalf("missing-note (%s %s %s %d) drifted.\n--- got ---\n%s\n--- want ---\n%s",
				url, owner, repo, strikes, got, want)
		}
	}
}

// TestDateProcessedFormat pins the REAL local-date format (the golden's
// <DATE> is the only normalization; the actual value must be today's
// local date, YYYY-MM-DD — datetime.now().strftime semantics).
func TestDateProcessedFormat(t *testing.T) {
	note := BuildNote(NoteArgs{URL: "https://github.com/x/y", RepoName: "y", Owner: "x"})
	today := localDateString()
	want := "date_processed: " + today
	if !strings.Contains(note, want) {
		t.Fatalf("note lacks %q (today local = %s)", want, today)
	}
	if m := dateProcessedRe.FindString(note); m == "" {
		t.Fatal("date_processed line does not match YYYY-MM-DD")
	}
	missing := BuildMissingRepoNote("https://github.com/x/y", "x", "y", 1)
	if !strings.Contains(missing, "date_recorded: "+today) {
		t.Fatalf("missing note lacks today's date_recorded (want %s)", today)
	}
	if !strings.Contains(missing, "Recorded "+today+" after") {
		t.Fatalf("missing note lacks 'Recorded %s after'", today)
	}
}

// TestBannerGateDropsTraversal double-covers the security control beyond
// the golden corpus: the emitted reference NEVER carries a path (only the
// gate-approved basename survives — "../x.png" yields a reference to x.png
// INSIDE attachments/banners/), and an unsafe basename is dropped.
func TestBannerGateDropsTraversal(t *testing.T) {
	// Path-prefixed inputs: ONLY the gate-approved basename survives —
	// the reference is always exactly attachments/banners/<basename>.
	for _, tc := range []struct{ in, base string }{
		{"../../etc/passwd.png", "passwd.png"},
		{"sub/../../x.png", "x.png"},
		{`a\..\b.png`, "b.png"},
		{"/abs/deep/dir/c.png", "c.png"},
		{`C:\banners\d.png`, "d.png"},
	} {
		cover, section := bannerRefs(tc.in)
		wantCover := "cover: attachments/banners/" + tc.base
		wantSection := "![banner](attachments/banners/" + tc.base + ")\n\n"
		if cover != wantCover || section != wantSection {
			t.Errorf("bannerRefs(%q) = (%q, %q), want (%q, %q)",
				tc.in, cover, section, wantCover, wantSection)
		}
	}
	// Unsafe basenames: dropped entirely.
	for _, evil := range []string{
		"evil.png]", "sp ace.png", `quote"d.png`, "tag[0].png",
	} {
		if cover, section := bannerRefs(evil); cover != "" || section != "" {
			t.Errorf("bannerRefs(%q) = (%q, %q), want dropped", evil, cover, section)
		}
	}
}
